CommandsServiceAsyncWaiter::CommandsServiceAsyncWaiter(
    CommandsService* proxy) : proxy_(proxy) {}

CommandsServiceAsyncWaiter::~CommandsServiceAsyncWaiter() = default;


void CommandsServiceAsyncWaiter::GetKeyFromCode(
    const std::string& code, std::string* out_key) {
  base::RunLoop loop;
  proxy_->GetKeyFromCode(
      std::move(code),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_key
,
             const std::string& key) {*out_key = std::move(key);
            loop->Quit();
          },
          &loop,
          out_key));
  loop.Run();
}

std::string CommandsServiceAsyncWaiter::GetKeyFromCode(
    const std::string& code) {
  std::string async_wait_result;
  GetKeyFromCode(std::move(code),&async_wait_result);
  return async_wait_result;
}




